const FLOW108={version:PAIJIAN_CONTENT.version,lessons:PAIJIAN_CONTENT.lessons,cards:PAIJIAN_CONTENT.cards,bank:PAIJIAN_CONTENT.bank,main:PAIJIAN_CONTENT.main,templates:PAIJIAN_CONTENT.templates};
function courseNext108(){return FLOW108.main.map(id=>DATA.lessons.find(l=>l.id===id)).find(l=>!state.done[l.id]&&!state.readDone?.[l.id])||DATA.lessons.find(l=>l.id===FLOW108.main[0])}
nextLesson=courseNext108;
const previousCourses108=courses;
courses=function(){previousCourses108();const app=$('#app'),next=courseNext108();const prep=DATA.lessons.find(l=>l.id===next.prerequisite);document.querySelectorAll('.lesson-item').forEach(row=>{const id=row.querySelector('[data-start]')?.dataset.start,l=DATA.lessons.find(l=>l.id===id);if(l)row.querySelector('small').textContent=l.track+' · 自由学习'+(l.suggested_background!=='无需先修'?' · 相关基础：'+l.suggested_background:'')});const panel=document.querySelector('.question-bank-panel');if(panel)panel.innerHTML='<h2>练习题库</h2><p>1000题 · 答案与原因 · 支持按课、牌、主题和错题练习</p><button class="primary" id="bank-open">开始练习</button>';if(!courseStage)app.insertAdjacentHTML('beforeend','<section class="panel stage-assessment-panel"><h2>阶段检验</h2><p class="tip">检查具体能力；首次作答与看答案后的练习分别记录。</p><div class="stage-assessment-actions">'+['认牌与观察','单牌情境解释','三牌综合解读'].map((x,i)=>'<button class="secondary" data-check="'+i+'">'+x+'</button>').join('')+'</div></section>');if($('#bank-open'))$('#bank-open').onclick=()=>bank108();document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>assessment108(Number(b.dataset.check)));bindStarts()};
let bankQueue108=[],bankIndex108=0,bankChoice108=null,bankShown108=false,bankReturn108=null;
function questionView108(q){return '<h2>'+E(q.question||q.prompt)+'</h2>'+q.options.map(o=>'<button class="option" data-banswer="'+o.id+'">'+o.id+'　'+E(o.text)+'</button>').join('')+'<button class="link" id="bshow">查看答案与原因</button><div id="bfeedback" aria-live="polite"></div>'}
function bank108(){session=null;tab='courses';const categories=[...new Set(FLOW108.bank.map(q=>q.category))];$('#app').innerHTML='<button class="link" id="bank-back">← 返回课程</button><h1>练习题库</h1><label>主题<select id="bank-category"><option value="">全部主题</option>'+categories.map(x=>'<option>'+E(x)+'</option>').join('')+'</select></label><label>课程<select id="bank-course"><option value="">全部课程</option>'+DATA.lessons.map(l=>'<option value="'+l.id+'">'+E(l.title)+'</option>').join('')+'</select></label><label>牌名搜索<input id="bank-card" type="search" placeholder="例如：愚者、圣杯"></label><label><input id="bank-wrong" type="checkbox"> 只练待复习题</label><p id="bank-count">共1000题</p><button class="primary" id="bank-go">开始一组8题</button><button class="secondary" id="bank-resume">继续上次题组</button>';
const filter=()=>FLOW108.bank.filter(q=>(!$('#bank-category').value||q.category===$('#bank-category').value)&&(!$('#bank-course').value||q.courseIds.includes($('#bank-course').value))&&(!$('#bank-card').value||(q.card_name||'').includes($('#bank-card').value.trim()))&&(!$('#bank-wrong').checked||Learning109.due(state.attempts||[],q.id)));['bank-category','bank-course','bank-card','bank-wrong'].forEach(id=>$('#'+id).oninput=()=>$('#bank-count').textContent='找到 '+filter().length+' 题');$('#bank-back').onclick=()=>navigate('courses');$('#bank-go').onclick=()=>{bankQueue108=Learning109.pick(filter(),state.attempts||[],8);if(!bankQueue108.length)return toast('没有符合条件的题目');bankIndex108=0;bankReturn108=null;bankChoice108=null;bankShown108=false;bankStudy108()};$('#bank-resume').onclick=()=>{const r=state.bankResume;if(!r)return toast('暂无未完成题组');bankQueue108=r.ids.map(id=>FLOW108.bank.find(q=>q.id===id)).filter(Boolean);bankIndex108=Math.min(r.index,bankQueue108.length-1);bankChoice108=r.choice;bankShown108=r.shown;bankStudy108()}}
function bankRemember108(){state.bankResume={ids:bankQueue108.map(q=>q.id),index:bankIndex108,choice:bankChoice108,shown:bankShown108};save()}
function bankStudy108(){const q=bankQueue108[bankIndex108];$('#app').innerHTML='<button class="link" id="bexit">← 保存进度并返回</button><p>练习 '+(bankIndex108+1)+' / '+bankQueue108.length+'</p>'+questionView108(q)+'<button class="secondary" id="bsource">回看相关解析</button><button class="primary" id="bnext">下一题</button>';const feedback=()=>{$('#bfeedback').innerHTML='<strong>参考答案：'+E(q.answer)+'</strong><p>原因：'+E(q.reason)+'</p>'+q.options.map(o=>'<p>'+o.id+'：'+E(o.feedback)+'</p>').join('')};if(bankChoice108||bankShown108)feedback();document.querySelectorAll('[data-banswer]').forEach(b=>b.onclick=()=>{if(!bankChoice108){state.attempts??=[];state.attempts.push({qid:q.id,answer:b.dataset.banswer,correct:b.dataset.banswer===q.answer_id,revealed:bankShown108,version:q.answerVersion,date:day(),time:new Date().toISOString(),independent:!bankShown108})}bankChoice108=b.dataset.banswer;feedback();bankRemember108()});$('#bshow').onclick=()=>{bankShown108=true;feedback();bankRemember108()};$('#bexit').onclick=()=>{bankRemember108();bank108()};$('#bnext').onclick=()=>{if(!bankChoice108&&!bankShown108)return toast('先作答或查看解释');if(++bankIndex108>=bankQueue108.length){delete state.bankResume;save();bank108();toast('本组练习完成')}else{bankChoice108=null;bankShown108=false;bankRemember108();bankStudy108()}};$('#bsource').onclick=()=>{bankRemember108();const l=DATA.lessons.find(l=>l.id===q.courseIds[0]);$('#app').innerHTML='<button class="primary" id="breturn">返回当前练习</button><h1>'+E(l.title)+'</h1>'+l.course_pages.map(p=>'<section class="panel"><h2>'+E(p.title)+'</h2>'+(p.card_names||[]).map(n=>cardImage(n)).join('')+p.paragraphs.map(t=>'<p>'+E(t)+'</p>').join('')+'</section>').join('');$('#breturn').onclick=bankStudy108};bankRemember108()}
function assessment108(stage){const categories=[['认牌观察','基础结构','观察与解释'],['情境·学习','情境·关系','牌位理解'],['牌阵学习','完整表达','迁移与检验']][stage];const pool=FLOW108.bank.filter(q=>categories.includes(q.category));let tasks=[];categories.forEach(c=>tasks.push(...Learning109.exam(pool.filter(q=>q.category===c),state.assessments||[],2)));tasks=tasks.slice(0,6);if(stage===2){tasks=tasks.slice(0,4);tasks.push({id:'CHECK3-CASE-'+((state.assessments||[]).filter(h=>h.stage===2).length%3),category:'三牌连接',question:['问题：本周怎样准备读书分享？已有材料但需要练习表达。','问题：怎样把读书笔记整理成分享？每天只有15分钟，资料还未核对。','问题：第一次给朋友分享阅读体验，如何准备？已有工具，需要核对论据。'][(state.assessments||[]).filter(h=>h.stage===2).length%3]+'现状星币八、需要留意隐士、建议魔术师，均正位。哪段解释回应了三个牌位？',card_names:['星币八','隐士','魔术师'],options:[{id:'A',text:'正在练习与整理；核对资料是否足够；利用现有工具做一版分享。',feedback:'三个位置分别回应现状、注意与行动，且未保证结果。'},{id:'B',text:'三张牌都表示成功，所以不用准备。',feedback:'忽略差异与牌位，并虚构确定结果。'},{id:'C',text:'隐士表示必须独自完成，不能向人求助。',feedback:'把一种读法变成唯一命令，未核对背景。'}],answer_id:'A',answer:'A',reason:'星币八的操作动作支持练习，隐士举灯可引导核对与整理，魔术师的工具支持资源运用；这是现代教学示例，并非原著逐句释义。',courseIds:['REC2-03']});tasks.push({id:'CHECK3-ORDER-'+((state.assessments||[]).filter(h=>h.stage===2).length%3),category:'综合步骤',question:'把三牌解读步骤按合理顺序点选排列。',sequence:['明确问题、背景和牌位','逐张描述画面依据','按牌位解释并连接','提出有条件行动并约定回看'],options:[],answer:'明确问题 → 观察 → 解释连接 → 行动与回看',reason:'先限定问题，再建立依据与位置关系，最后落到可检验的行动；不是先编故事再找牌面支持。',courseIds:['REC2-02']})}let i=0,results=[],revealed=false,chosen=false;function show(){const q=tasks[i];$('#app').innerHTML='<button class="link" id="checkback">← 返回课程</button><h1>'+['认牌与观察','单牌情境解释','三牌综合解读'][stage]+'</h1><p>任务 '+(i+1)+' / '+tasks.length+'</p>'+(q.card_names?q.card_names.map(n=>cardImage(n)).join(''):q.card_name?cardImage(q.card_name):'')+(q.sequence?'<h2>'+E(q.question)+'</h2>'+[2,0,3,1].map(j=>'<button class="option" data-sequence="'+j+'">'+E(q.sequence[j])+'</button>').join('')+'<div id="bfeedback" aria-live="polite"></div><button class="link" id="bshow">查看参考顺序</button>':questionView108(q))+'<button class="primary" id="checknext">下一项</button>';$('#checkback').onclick=()=>navigate('courses');if(q.sequence){let order=[];document.querySelectorAll('[data-sequence]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.sequence);if(order.includes(n)||chosen)return;order.push(n);b.disabled=true;$('#bfeedback').textContent=order.map(n=>q.sequence[n]).join(' → ');if(order.length===4){results.push({qid:q.id,prompt:q.question,courseIds:q.courseIds,dimension:q.category,correct:order.every((n,j)=>n===j),independent:!revealed});chosen=true;$('#bfeedback').innerHTML+='<p>参考顺序：'+E(q.answer)+'</p><p>'+E(q.reason)+'</p>'}})}document.querySelectorAll('[data-banswer]').forEach(b=>b.onclick=()=>{if(!chosen){results.push({qid:q.id,prompt:q.question,courseIds:q.courseIds,dimension:q.category,correct:b.dataset.banswer===q.answer_id,independent:!revealed});chosen=true}$('#bfeedback').innerHTML='<p>'+E(q.answer)+'</p><p>'+E(q.reason)+'</p>'+q.options.map(o=>'<p>'+o.id+' '+E(o.feedback)+'</p>').join('')});$('#bshow').onclick=()=>{revealed=true;$('#bfeedback').innerHTML='<p>'+E(q.answer)+'</p><p>'+E(q.reason)+'</p>'};$('#checknext').onclick=()=>{if(!chosen)return toast('请先作答，查看答案后也可以练习');if(++i<tasks.length){revealed=false;chosen=false;show()}else finish()}}function finish(){state.assessments??=[];state.assessments.push({stage,date:day(),results});save();$('#app').innerHTML='<h1>本次检验记录</h1><p>以下只代表本次任务表现，可继续在实际记录中检验。</p>'+results.map(r=>{const q=tasks.find(q=>q.id===r.qid);return '<section class="panel"><h3>'+E(r.dimension)+'</h3><p>'+E(q.question)+'</p><strong>'+(r.independent?(r.correct?'首次独立回答正确':'建议再练'):'提示后作答')+'</strong><button class="link" data-start="'+q.courseIds[0]+'">回看相关课程</button></section>'}).join('')+'<button class="primary" id="checkdone">返回课程</button>';bindStarts();$('#checkdone').onclick=()=>navigate('courses')}show()}
const oldBindReading108=bindReadingPanel;
bindReadingPanel=function(l){oldBindReading108(l);const panel=$('#course-reading-panel');panel.insertAdjacentHTML('beforeend','<section class="inline-task"><h3>学完试一次</h3><p>'+E(l.practice_task)+'</p>'+FLOW108.templates.filter(t=>t.courseId===l.id).map(t=>'<button class="primary" data-record-template="'+t.id+'">用这个牌阵记录'+(t.id.endsWith('T1')?'':' · '+t.id.split('-').slice(-1)[0])+'</button>').join('')+'<button class="secondary" id="course-task-note">去记录理解</button></section>');$('#course-task-note').onclick=()=>{const cid=DATA.cards.find(c=>c.name===l.related_cards?.[0])?.card_id||'';const note={...freshNote(cid),type:cid?'single':'life',courseId:l.id,taskPrompt:l.practice_task};state.courseReturn={id:l.id,page:session?.readingPage||0};editJournal(note)};document.querySelectorAll('[data-record-template]').forEach(b=>b.onclick=()=>{const t=FLOW108.templates.find(t=>t.id===b.dataset.recordTemplate);state.courseReturn={id:l.id,page:session?.readingPage||0};editSpread({...freshSpread(),template:'custom',labels:t.positions.map(p=>p.label),templateSnapshot:JSON.parse(JSON.stringify(t)),courseId:l.id})})};
const oldEditJournal108=editJournal,oldEditSpread108=editSpread;
editJournal=function(e){oldEditJournal108(e);if(e.courseId){$('#app').insertAdjacentHTML('afterbegin','<div class="panel"><p>'+E(e.taskPrompt||'本课实践记录')+'</p><button class="link" id="record-course-back">返回关联课程</button></div>');$('#record-course-back').onclick=()=>{if(journalFlush&&journalFlush()===false)return;start(e.courseId)}}};
editSpread=function(e,step=1){oldEditSpread108(e,step);if(e.templateSnapshot){$('#app').insertAdjacentHTML('afterbegin','<section class="panel"><h3>'+E(e.templateSnapshot.name)+'</h3>'+textbookLayout(e.templateSnapshot.positions)+'<p>'+E(e.templateSnapshot.orientationRule)+'</p><button class="link" id="record-course-back">返回关联课程</button></section>');document.querySelectorAll('[data-layout-pick]').forEach(b=>b.onclick=()=>{const p=e.templateSnapshot.positions.find(p=>p.number===Number(b.dataset.layoutPick));$('#layout-definition').textContent=p.label+'：'+p.definition});$('#record-course-back').onclick=()=>{if(journalFlush&&journalFlush()===false)return;start(e.courseId)}}};
render();
